package com.example.serialization

import kotlinx.coroutines.*
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.serialization.*
import kotlinx.serialization.json.*
import java.util.concurrent.ConcurrentHashMap
import java.nio.charset.Charset
import java.util.Base64

@Serializable
data class UserCommand(
    val action: String,
    val target: String,
    val payload: String = ""
)

class EncodingNormalizer {
    private val normalizationCache = ConcurrentHashMap<String, String>()
    private val mutex = Mutex()
    private var pendingNormalization: String? = null

    suspend fun normalize(input: String): String {
        normalizationCache[input]?.let { return it }

        return mutex.withLock {
            pendingNormalization = input
            val result = performNormalization(input)
            normalizationCache[input] = result
            pendingNormalization = null
            result
        }
    }

    private fun performNormalization(input: String): String {
        // Normalize Unicode to ASCII-safe representation
        val bytes = input.toByteArray(Charsets.UTF_8)
        val normalized = StringBuilder()
        var i = 0
        while (i < bytes.size) {
            val b = bytes[i].toInt() and 0xFF
            if (b < 0x80) {
                normalized.append(b.toChar())
            } else if (b >= 0xC0 && b < 0xE0 && i + 1 < bytes.size) {
                // 2-byte UTF-8 sequence - decode to codepoint
                val cp = ((b and 0x1F) shl 6) or (bytes[i + 1].toInt() and 0x3F)
                // Map to ASCII equivalent if possible (e.g., fullwidth chars)
                val mapped = mapToAscii(cp)
                normalized.append(mapped)
                i += 1
            } else if (b >= 0xE0 && b < 0xF0 && i + 2 < bytes.size) {
                // 3-byte UTF-8 sequence
                val cp = ((b and 0x0F) shl 12) or
                        ((bytes[i + 1].toInt() and 0x3F) shl 6) or
                        (bytes[i + 2].toInt() and 0x3F)
                val mapped = mapToAscii(cp)
                normalized.append(mapped)
                i += 2
            } else {
                normalized.append('?')
            }
            i++
        }
        return normalized.toString()
    }

    private fun mapToAscii(codepoint: Int): Char {
        return when (codepoint) {
            in 0xFF01..0xFF5E -> (codepoint - 0xFEE0).toChar() // Fullwidth to ASCII
            0x2044 -> '/'  // Fraction slash
            0x2215 -> '/'  // Division slash  
            0xFF0F -> '/'  // Fullwidth solidus
            0x2025 -> '.'  // Two dot leader -> period
            0xFF0E -> '.'  // Fullwidth full stop
            else -> '?'
        }
    }
}

class CommandValidator {
    private val blockedPatterns = listOf(
        Regex("""\.\.[\\/]"""),
        Regex("""[;|&`\$]""")
    )

    fun isValid(command: UserCommand): Boolean {
        // Check action is alphanumeric
        if (!command.action.matches(Regex("^[a-zA-Z]+$"))) return false
        // Check target doesn't contain path traversal or injection
        for (pattern in blockedPatterns) {
            if (pattern.containsMatchIn(command.target)) return false
        }
        return true
    }
}

class SecureCommandProcessor {
    private val json = Json { ignoreUnknownKeys = true }
    private val normalizer = EncodingNormalizer()
    private val validator = CommandValidator()
    private val executionLog = mutableListOf<String>()

    suspend fun processRequest(rawInput: String): Result<String> {
        return try {
            // Step 1: Decode from Base64 transport encoding
            val decoded = String(Base64.getDecoder().decode(rawInput), Charsets.UTF_8)

            // Step 2: Parse JSON
            val command = json.decodeFromString<UserCommand>(decoded)

            // Step 3: Validate BEFORE normalization
            if (!validator.isValid(command)) {
                return Result.failure(SecurityException("Invalid command rejected"))
            }

            // Step 4: Normalize encoding for consistent processing
            val normalizedTarget = normalizer.normalize(command.target)
            val normalizedCommand = command.copy(target = normalizedTarget)

            // Step 5: Execute the validated command
            executeCommand(normalizedCommand)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    private suspend fun executeCommand(command: UserCommand): Result<String> {
        return withContext(Dispatchers.IO) {
            when (command.action) {
                "read" -> readFile(command.target)
                "list" -> listDirectory(command.target)
                "info" -> Result.success("Info: ${command.target}")
                else -> Result.failure(IllegalArgumentException("Unknown action"))
            }
        }
    }

    private fun readFile(path: String): Result<String> {
        executionLog.add("READ: $path")
        // Simulated file read - in production this hits the filesystem
        return Result.success("Contents of: $path")
    }

    private fun listDirectory(path: String): Result<String> {
        executionLog.add("LIST: $path")
        return Result.success("Listing: $path")
    }

    fun getLog(): List<String> = executionLog.toList()
}

fun main() = runBlocking {
    val processor = SecureCommandProcessor()

    // Normal request
    val normalPayload = Base64.getEncoder().encodeToString(
        """{"action":"read","target":"documents/report.txt"}""".toByteArray()
    )
    println(processor.processRequest(normalPayload))

    // Attempt with fullwidth characters (bypass)
    val bypassPayload = Base64.getEncoder().encodeToString(
        """{"action":"read","target":"\uFF0E\uFF0E\uFF0Fetc\uFF0Fpasswd"}""".toByteArray()
    )
    println(processor.processRequest(bypassPayload))
    println("Log: ${processor.getLog()}")
}
